/**
 * Miami DJ Beat — The AI Booth · ElevenLabs TTS (client)
 *
 * No ElevenLabs API key in the browser. Audio is generated by Edge Function `booth-tts`.
 * Requires: supabase-config.js (MDB_SUPABASE_URL, MDB_SUPABASE_ANON_KEY)
 *
 * Usage:
 *   await window.MDJBoothTTS.speak('Bienvenido a la central de operaciones.');
 *   window.MDJBoothTTS.stop();
 */
(function () {
  'use strict';

  let _lastObjectUrl = null;

  function _baseUrl() {
    var u = window.MDB_SUPABASE_URL || '';
    if (!u) console.warn('[booth-elevenlabs] MDB_SUPABASE_URL missing');
    return u.replace(/\/$/, '');
  }

  function _anon() {
    return window.MDB_SUPABASE_ANON_KEY || '';
  }

  function stop() {
    try {
      if (window.__mdjBoothAudio) {
        window.__mdjBoothAudio.pause();
        window.__mdjBoothAudio.src = '';
        window.__mdjBoothAudio = null;
      }
      if (_lastObjectUrl) {
        URL.revokeObjectURL(_lastObjectUrl);
        _lastObjectUrl = null;
      }
    } catch (e) {
      /* ignore */
    }
  }

  /**
   * @param {string} text — Plain text for TTS (Spanish/English).
   * @returns {Promise<void>}
   */
  async function speak(text) {
    stop();
    var t = typeof text === 'string' ? text.trim() : '';
    if (!t) return;

    var base = _baseUrl();
    var key = _anon();
    if (!base || !key) {
      throw new Error('Supabase URL o anon key no configurados (supabase-config.js).');
    }

    var url =
      typeof window.mdbSupabaseFunctionUrl === 'function'
        ? window.mdbSupabaseFunctionUrl('booth-tts')
        : base + '/functions/v1/booth-tts';
    var res = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: 'Bearer ' + key,
        apikey: key,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ text: t }),
    });

    if (!res.ok) {
      var errBody = await res.text();
      throw new Error('booth-tts ' + res.status + ': ' + errBody);
    }

    var blob = await res.blob();
    _lastObjectUrl = URL.createObjectURL(blob);
    var audio = new Audio(_lastObjectUrl);
    window.__mdjBoothAudio = audio;
    audio.setAttribute('playsinline', '');
    await audio.play();
  }

  window.MDJBoothTTS = {
    speak: speak,
    stop: stop,
  };
})();
